CREATE OR REPLACE FUNCTION public.guard_order_discount() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE threshold numeric; BEGIN SELECT discount_approval_threshold_pct INTO threshold FROM public.tenant_settings WHERE tenant_id=NEW.tenant_id; IF NEW.document_status='final' AND NEW.discount_pct>COALESCE(threshold,0) AND NOT EXISTS(SELECT 1 FROM public.approval_requests r WHERE r.tenant_id=NEW.tenant_id AND r.entity_type='orders' AND r.entity_id=NEW.id AND r.type='discount' AND r.status='approved' AND (r.payload->>'discount_pct')::numeric=NEW.discount_pct AND r.payload->>'invoice_number'=NEW.invoice_number) THEN RAISE EXCEPTION 'Diskon memerlukan persetujuan Master sebelum dokumen final'; END IF; RETURN NEW; END $$;
CREATE TRIGGER zz_order_discount BEFORE INSERT OR UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.guard_order_discount();
CREATE OR REPLACE FUNCTION public.save_order_atomic(p_order_id uuid,p_order jsonb,p_items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid:=public.active_tenant_id(); oid uuid; seq bigint; code text; num text; fmt text; item jsonb; itemid uuid; ids uuid[]:='{}'::uuid[]; d date; BEGIN IF NOT public.can_access_tenant_module(tid,'orders') THEN RAISE EXCEPTION 'Order tidak berizin'; END IF; IF NULLIF(btrim(p_order->>'client_name'),'') IS NULL OR jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'Client dan minimal satu item wajib'; END IF; IF p_order ? 'tenant_id' AND (p_order->>'tenant_id')::uuid<>tid THEN RAISE EXCEPTION 'Tenant tidak berizin'; END IF; d:=COALESCE(NULLIF(p_order->>'invoice_date','')::date,(now() AT TIME ZONE 'Asia/Jakarta')::date); num:=NULLIF(btrim(p_order->>'invoice_number'),''); IF p_order_id IS NULL THEN IF num IS NULL THEN code:=regexp_replace(upper(p_order->>'client_name'),'[^A-Z0-9]','','g'); INSERT INTO public.document_counters(tenant_id,client_code,document_type,sequence) VALUES(tid,code,'invoice',1) ON CONFLICT(tenant_id,client_code,document_type) DO UPDATE SET sequence=public.document_counters.sequence+1 RETURNING sequence INTO seq; SELECT COALESCE(doc_numbering->>'invoice','INV/{CLIENT}/{YYYY}/{MM}/{SEQ}') INTO fmt FROM public.tenant_settings WHERE tenant_id=tid; num:=replace(replace(replace(replace(fmt,'{CLIENT}',code),'{YYYY}',to_char(d,'YYYY')),'{MM}',to_char(d,'MM')),'{SEQ}',seq::text); END IF; INSERT INTO public.orders(tenant_id,client_name,client_address,po_number,section,invoice_number,invoice_date,due_date,notes,created_by) VALUES(tid,btrim(p_order->>'client_name'),NULLIF(p_order->>'client_address',''),NULLIF(p_order->>'po_number',''),NULLIF(p_order->>'section',''),num,d,NULLIF(p_order->>'due_date','')::date,NULLIF(p_order->>'notes',''),NULLIF(p_order->>'created_by','')) RETURNING id INTO oid; ELSE SELECT id INTO oid FROM public.orders WHERE id=p_order_id AND tenant_id=tid AND deleted_at IS NULL FOR UPDATE; IF oid IS NULL THEN RAISE EXCEPTION 'Order tidak ditemukan'; END IF; UPDATE public.orders SET client_name=btrim(p_order->>'client_name'),client_address=NULLIF(p_order->>'client_address',''),po_number=NULLIF(p_order->>'po_number',''),section=NULLIF(p_order->>'section',''),invoice_number=COALESCE(num,invoice_number),invoice_date=d,due_date=NULLIF(p_order->>'due_date','')::date,notes=NULLIF(p_order->>'notes',''),created_by=NULLIF(p_order->>'created_by','') WHERE id=oid AND tenant_id=tid; END IF; FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP IF NULLIF(btrim(item->>'item_name'),'') IS NULL THEN RAISE EXCEPTION 'Nama item wajib'; END IF; itemid:=NULLIF(item->>'id','')::uuid; IF itemid IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.order_items WHERE id=itemid AND order_id=oid AND tenant_id=tid AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Item tidak berizin'; END IF; UPDATE public.order_items SET item_name=btrim(item->>'item_name'),qty=(item->>'qty')::numeric,price=(item->>'price')::numeric,unit=COALESCE(NULLIF(item->>'unit',''),'pcs'),position=cardinality(ids)+1 WHERE id=itemid AND tenant_id=tid; ELSE INSERT INTO public.order_items(tenant_id,order_id,item_name,qty,price,unit,position) VALUES(tid,oid,btrim(item->>'item_name'),(item->>'qty')::numeric,(item->>'price')::numeric,COALESCE(NULLIF(item->>'unit',''),'pcs'),cardinality(ids)+1) RETURNING id INTO itemid; END IF; ids:=array_append(ids,itemid); END LOOP; IF EXISTS(SELECT 1 FROM public.order_items WHERE order_id=oid AND tenant_id=tid AND deleted_at IS NULL AND NOT(id=ANY(ids))) THEN RAISE EXCEPTION 'Arsipkan item melalui persetujuan terlebih dahulu'; END IF; RETURN oid; END $$;
CREATE OR REPLACE FUNCTION public.suggest_invoice_number(p_client_name text,p_invoice_date date) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE code text; seq bigint; fmt text; tid uuid:=public.active_tenant_id(); BEGIN IF NOT public.can_access_tenant_module(tid,'orders') THEN RAISE EXCEPTION 'Tidak berizin'; END IF; code:=regexp_replace(upper(p_client_name),'[^A-Z0-9]','','g'); SELECT COALESCE(sequence,0)+1 INTO seq FROM public.document_counters WHERE tenant_id=tid AND client_code=code AND document_type='invoice'; SELECT COALESCE(doc_numbering->>'invoice','INV/{CLIENT}/{YYYY}/{MM}/{SEQ}') INTO fmt FROM public.tenant_settings WHERE tenant_id=tid; RETURN replace(replace(replace(replace(fmt,'{CLIENT}',code),'{YYYY}',to_char(p_invoice_date,'YYYY')),'{MM}',to_char(p_invoice_date,'MM')),'{SEQ}',COALESCE(seq,1)::text); END $$;
CREATE OR REPLACE FUNCTION public.create_shipment_atomic(p_order_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; sid uuid; tid uuid:=public.active_tenant_id(); BEGIN IF NOT public.can_access_tenant_module(tid,'orders') AND NOT public.can_access_tenant_module(tid,'shipments') THEN RAISE EXCEPTION 'Tidak berizin'; END IF; SELECT * INTO o FROM public.orders WHERE id=p_order_id AND tenant_id=tid AND deleted_at IS NULL FOR UPDATE; IF o.id IS NULL THEN RAISE EXCEPTION 'Order tidak ditemukan'; END IF; SELECT id INTO sid FROM public.shipments WHERE order_id=o.id AND tenant_id=tid AND deleted_at IS NULL ORDER BY created_at LIMIT 1; IF sid IS NOT NULL THEN RETURN sid; END IF; INSERT INTO public.shipments(tenant_id,order_id,ship_to,section,do_number,delivery_date,stored_by,delivery_by) VALUES(tid,o.id,o.client_name,o.section,replace(replace(o.invoice_number,'/INV/','/DO/'),'INV/','DO/'),(now() AT TIME ZONE 'Asia/Jakarta')::date,o.created_by,o.created_by) RETURNING id INTO sid; RETURN sid; END $$;
CREATE OR REPLACE FUNCTION public.guard_tenant_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id THEN RAISE EXCEPTION 'tenant_id tidak boleh diubah'; END IF; RETURN NEW; END $$;
DO $block$ DECLARE tbl text; BEGIN FOREACH tbl IN ARRAY ARRAY['clients','orders','order_items','shipments','pricelist_items','payables','receivables','cash_requests','expenses','tasks','team_members','user_roles','module_access'] LOOP EXECUTE format('ALTER TABLE public.%I ALTER COLUMN tenant_id SET NOT NULL',tbl); END LOOP; FOREACH tbl IN ARRAY ARRAY['user_roles','module_access','tenant_memberships','tenant_settings','approval_requests'] LOOP EXECUTE format('CREATE TRIGGER tenant_immutable BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_tenant_immutable()',tbl); END LOOP; END $block$;
CREATE INDEX audit_tenant_date ON public.audit_logs(tenant_id,created_at DESC); CREATE INDEX approval_tenant_status ON public.approval_requests(tenant_id,status);
REVOKE ALL ON FUNCTION public.save_order_atomic(uuid,jsonb,jsonb),public.suggest_invoice_number(text,date),public.create_shipment_atomic(uuid),public.guard_order_discount(),public.guard_tenant_immutable() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_order_atomic(uuid,jsonb,jsonb),public.suggest_invoice_number(text,date),public.create_shipment_atomic(uuid) TO authenticated,service_role;